from __future__ import annotations
from typing import Sequence, Any

class FeaturePipeline:
    def __init__(self, steps: Sequence[tuple[str, Any]]):
        self.steps = list(steps)

    def fit(self, X: Sequence[Sequence[Any]]) -> FeaturePipeline:
        cur = X
        for name, transformer in self.steps[:-1]:
            cur = transformer.fit_transform(cur)
        if self.steps:
            self.steps[-1][1].fit(cur)
        return self

    def transform(self, X: Sequence[Sequence[Any]]) -> list[list[float]]:
        cur = X
        for name, transformer in self.steps:
            cur = transformer.transform(cur)
        return cur  # type: ignore

    def fit_transform(self, X: Sequence[Sequence[Any]]) -> list[list[float]]:
        return self.fit(X).transform(X)

    def inverse_transform(self, X: Sequence[Sequence[Any]]) -> list[list[Any]]:
        cur = X
        for name, transformer in reversed(self.steps):
            cur = transformer.inverse_transform(cur)
        return cur

