from __future__ import annotations
import math
from collections import Counter
from typing import Sequence, Any

class SimpleImputer:
    def __init__(self, strategy: str = 'mean'):
        if strategy not in ('mean', 'median', 'most_frequent'):
            raise ValueError(f'Unknown strategy: {strategy}')
        self.strategy = strategy
        self.statistics: list[float] = []

    def fit(self, X: Sequence[Sequence[Any]]) -> SimpleImputer:
        if not X or not X[0]:
            return self
        n_cols = len(X[0])
        self.statistics = []
        for c in range(n_cols):
            valid = []
            for r in range(len(X)):
                val = X[r][c]
                if val is not None and not (isinstance(val, float) and math.isnan(val)):
                    valid.append(float(val))
            if not valid:
                self.statistics.append(0.0)
                continue
            if self.strategy == 'mean':
                self.statistics.append(sum(valid) / len(valid))
            elif self.strategy == 'median':
                valid.sort()
                mid = len(valid) // 2
                med = valid[mid] if len(valid) % 2 == 1 else (valid[mid - 1] + valid[mid]) / 2.0
                self.statistics.append(med)
            elif self.strategy == 'most_frequent':
                cnt = Counter(valid)
                self.statistics.append(cnt.most_common(1)[0][0])
        return self

    def transform(self, X: Sequence[Sequence[Any]]) -> list[list[float]]:
        out = []
        for row in X:
            new_row = []
            for c, val in enumerate(row):
                if val is None or (isinstance(val, float) and math.isnan(val)):
                    new_row.append(self.statistics[c])
                else:
                    new_row.append(float(val))
            out.append(new_row)
        return out

    def fit_transform(self, X: Sequence[Sequence[Any]]) -> list[list[float]]:
        return self.fit(X).transform(X)

